var existing = element.parentNode.querySelector('.cta-button-below-title');
if (existing) return;

var wrapper = document.createElement('div');
wrapper.style.marginTop = '12px';

var btn = document.createElement('a');
btn.href = 'https://support.fandom.com/hc/en-us/requests/new?ticket_form_id=360000931354&tf_360017817454=i_want_a_feature_or_extension_turned_on';
btn.textContent = 'Request a Feature or Extension';
btn.className = 'cta-button-below-title';
btn.style.display = 'inline-block';
btn.style.padding = '12px 24px';
btn.style.backgroundColor = '#520044';
btn.style.color = '#ffffff';
btn.style.fontSize = '16px';
btn.style.fontWeight = 'bold';
btn.style.textDecoration = 'none';
btn.style.borderRadius = '6px';
btn.style.border = 'none';
btn.style.cursor = 'pointer';
btn.style.transition = 'background-color 0.2s ease';

wrapper.appendChild(btn);
element.parentNode.appendChild(wrapper);
